await new Promise(r => setTimeout(r, 500));

// 4. 观察两次操作分别触发的事件
console.log('events:', JSON.stringify(events));

// 5. 清理监听
const removed = eda.pcb_Event.removeEventListener(listenerId);
console.log('removed:', removed);
